//! 🔁️ Explicit recursive receiving cuts conditional trait selection while retaining typed child owner bounds.
use super::*;
#[test]fn unit_enum_receiver_uses_the_trait_associated_type_not_an_enum_variant(){let input:syn::DeriveInput=syn::parse_str("enum Tag { Value }").unwrap();let output=expand(&input).unwrap().to_string();assert!(output.contains("NativeUnitEnumReceiver :: new"));assert!(!output.contains("Self :: Receiver :: new"));let parsed:syn::File=syn::parse_str(&output).unwrap();let method=parsed.items.iter().filter_map(|item|if let syn::Item::Impl(item)=item{Some(item)}else{None}).flat_map(|item|item.items.iter()).find_map(|item|if let syn::ImplItem::Fn(method)=item{(method.sig.ident=="receiver").then_some(method)}else{None}).unwrap();let syn::ReturnType::Type(_,output)=&method.sig.output else{panic!("unit receiver requires its associated output")};let syn::Type::Path(output)=output.as_ref()else{panic!("unit receiver output requires its original trait projection")};assert!(output.qself.is_some());assert_eq!(output.path.segments.last().unwrap().ident,"Receiver");assert!(output.path.segments.iter().any(|segment|segment.ident=="NativeReceive"));}
#[test]fn declared_recursive_receivers_have_unconditional_original_type_implementations(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){for source in case["sources"].as_array().unwrap(){let input:syn::DeriveInput=syn::parse_str(source.as_str().unwrap()).unwrap();let output=expand(&input).unwrap();let parsed:syn::File=syn::parse2(output).unwrap();let implementation=parsed.items.iter().find_map(|item|{let syn::Item::Impl(item)=item else{return None};item.trait_.as_ref().and_then(|(_,path,_)|path.segments.last()).is_some_and(|segment|segment.ident=="NativeReceive").then_some(item)}).unwrap();let recursive=case["recursive"].as_array().unwrap().iter().any(|value|value.as_str()==Some(input.ident.to_string().as_str()));if recursive{assert!(implementation.generics.where_clause.is_none());}let receiver=parsed.items.iter().find_map(|item|{let syn::Item::Struct(item)=item else{return None};(item.ident==format!("{}NativeReceiver",input.ident)).then_some(item)}).unwrap();assert!(receiver.generics.where_clause.is_some());}}}

#[test]fn recursive_receiving_is_an_explicit_bare_container_flag(){let plain:syn::DeriveInput=syn::parse_str("struct Leaf { value:u64 }").unwrap();assert!(!super::super::parse_container_attrs(&plain.attrs).unwrap().receive_recursive);let recursive:syn::DeriveInput=syn::parse_str("#[value(receive_recursive)] struct Branch { children:Vec<Branch> }").unwrap();assert!(super::super::parse_container_attrs(&recursive.attrs).unwrap().receive_recursive);let valued:syn::DeriveInput=syn::parse_str("#[value(receive_recursive=\"true\")] struct Branch { children:Vec<Branch> }").unwrap();assert!(super::super::parse_container_attrs(&valued.attrs).is_err());}

fn required_flags(source:&str)->String{let input:syn::DeriveInput=syn::parse_str(source).unwrap();let output:syn::File=syn::parse2(expand(&input).unwrap()).unwrap();let receiver=output.items.iter().find_map(|item|if let syn::Item::Struct(item)=item{Some(item)}else{None}).unwrap();let Data::Struct(data)=&input.data else{unreachable!()};data.fields.iter().map(|field|{let expected=format!("default_{}",field.ident.as_ref().unwrap());(!receiver.fields.iter().any(|field|field.ident.as_ref().is_some_and(|name|name==expected.as_str()))).to_string()}).collect::<Vec<_>>().join(",")}
#[test]fn native_receiving_never_bypasses_an_authored_validation_port(){for source in ["#[value(validate=\"crate::check\")] struct Record { a:u64 }","#[value(validate_controlled=\"crate::check\")] enum Choice { One, Two }","#[value(transparent,deserialize_controlled_with=\"crate::check\")] struct Scalar(u64);"]{let input:syn::DeriveInput=syn::parse_str(source).unwrap();assert!(expand(&input).unwrap_err().to_string().contains("authored controlled owner port"));}}
#[test]fn a_path_default_never_substitutes_the_type_default_and_stays_natively_required(){
 assert_eq!(required_flags("struct S { #[value(default=\"crate::f\")] a:u8, b:u8, #[value(default)] c:u8, d:Option<u8> }"),"true,true,false,false");
 assert_eq!(required_flags("struct S { #[value(default=\"crate::f\")] a:Option<u8> }"),"true");
 assert_eq!(required_flags("#[value(default)] struct S { #[value(default=\"crate::f\")] a:u8, b:u8 }"),"true,false");
}

#[test]fn generated_receivers_use_the_canonical_nested_primary_for_every_authored_root(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in corpus["primaryPathCases"].as_array().unwrap(){let input:syn::DeriveInput=syn::parse_str(row["source"].as_str().unwrap()).unwrap();let output=expand(&input).unwrap();let _:syn::File=syn::parse2(output.clone()).unwrap();let text=output.to_string().replace(" ","");let root=row["root"].as_str().unwrap();assert!(text.contains(&format!("::{root}::native_decoding::OriginalReceivingPrimary")),"{text}");assert!(!text.contains(&format!("::{root}::OriginalReceivingPrimary")));}}

#[test]
fn generated_original_closure_ports_preserve_actual_pending_types(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("retirement-poll.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let input:syn::DeriveInput=syn::parse_str(row["source"].as_str().unwrap()).unwrap();let parsed:syn::File=syn::parse2(expand(&input).unwrap()).unwrap();let receiver=parsed.items.iter().find_map(|item|{let syn::Item::Impl(item)=item else{return None};item.trait_.as_ref().and_then(|(_,path,_)|path.segments.last()).is_some_and(|segment|segment.ident=="NativeReceiver").then_some(item)}).unwrap();for port in corpus["ports"].as_array().unwrap(){let port=port.as_str().unwrap();let method=receiver.items.iter().find_map(|item|{let syn::ImplItem::Fn(method)=item else{return None};(method.sig.ident==port).then_some(method)}).unwrap();let syn::ReturnType::Type(_,output)=&method.sig.output else{panic!("original closure has no Poll output")};let syn::Type::Path(output)=output.as_ref()else{panic!("original closure is not a named Poll")};assert_eq!(output.path.segments.last().unwrap().ident,corpus["output"].as_str().unwrap());}}
}
